	PID,
	AREA_NO_ID,
	AREA_DSCR,
	PERIOD_FLAG,
	INDEX_NAME,
	SUM(INDEX_VALUE) ,
	SUM(GROWTH_INDEX_VALUE)
    FROM
	(

SELECT
	A0.D_ACCT			 	AS DATA_DATE,
	a1.PID,
	a1.AREA_NO_ID,
	a1.AREA_DSCR,
	'1'					AS PERIOD_FLAG,
	'库存'					AS INDEX_NAME,
	ROUND(SUM(a0.F_BALANCE), 4) 		AS INDEX_VALUE,
	0					AS GROWTH_INDEX_VALUE
FROM
	stg.trs_tmis_stock a0
  LEFT JOIN
    (SELECT DISTINCT
      p.GUOKU_ID AS PID,
