	'4' AS PERIOD_FLAG,
	'非税收收入当期值'AS  INDEX_NAME         ,
	SUM(lib.INDEX_VALUE)
    FROM visual_screen.vs_tax_revenue lib
	WHERE  LEFT(lib.DACCT,4)= LEFT(V_DATA_DATE,4)
	AND  lib.PERIOD_FLAG='2'
	AND lib.INDEX_NAME= '非税收收入当期值'
	GROUP BY
	lib.AREA_CODE;

